    for p in item['premises_fol'] + [item['conclusion_fol']]:
        if p.count('(') != p.count(')'):
            unbalanced.append((item['id'], p))
print(f'Unbalanced parens: {len(unbalanced)} formulas')
for id, p in unbalanced[:10]:
    print(f'  [{id}]: {p}')

# Find all quantifier+variable patterns more precisely
