for item in d:
    for p in item['premises_fol'] + [item['conclusion_fol']]:
        qvars = re.findall(r'[∀∃]([a-z]\d?)', p)
        all_qvars.update(qvars)
print(f'\\nAll quantifier variables: {sorted(all_qvars)}')
"

